"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[2071],{22071:e=>{e.exports=JSON.parse('{"slug":"vvp-kitaya-3-kvartal-2026-eksport","locale":"ru","title":"\u042d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0430 \u041a\u0438\u0442\u0430\u044f \u0443\u0441\u043a\u043e\u0440\u0438\u043b\u0430\u0441\u044c \u0434\u043e 4,5% \u043d\u0430 \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u0435, \u0430 \u0440\u043e\u0437\u043d\u0438\u0447\u043d\u044b\u0435 \u043f\u0440\u043e\u0434\u0430\u0436\u0438 \u0432\u044b\u0440\u043e\u0441\u043b\u0438 \u0432\u0441\u0435\u0433\u043e \u043d\u0430 1,1%","description":"\u0412\u0412\u041f \u041a\u0438\u0442\u0430\u044f \u0432 III \u043a\u0432\u0430\u0440\u0442\u0430\u043b\u0435 2026 \u0433\u043e\u0434\u0430 \u0432\u044b\u0440\u043e\u0441 \u043d\u0430 4,5%. \u042d\u043a\u0441\u043f\u043e\u0440\u0442 \u043f\u0440\u0438\u0431\u0430\u0432\u0438\u043b 36%, \u0440\u043e\u0437\u043d\u0438\u0446\u0430 1,1%. \u041f\u043e\u0447\u0435\u043c\u0443 \u0440\u043e\u0441\u0442 \u043d\u0430 \u0432\u043d\u0435\u0448\u043d\u0435\u043c \u0441\u043f\u0440\u043e\u0441\u0435 \u0445\u0440\u0443\u043f\u043a\u0438\u0439 \u0438 \u0447\u0442\u043e \u044d\u0442\u043e \u0437\u043d\u0430\u0447\u0438\u0442 \u0434\u043b\u044f \u0420\u043e\u0441\u0441\u0438\u0438.","blocks":[{"id":"b001","kind":"paragraph","text":"\u0412\u0412\u041f \u041a\u0438\u0442\u0430\u044f \u0432 \u0438\u044e\u043b\u0435–\u0441\u0435\u043d\u0442\u044f\u0431\u0440\u0435 \u0432\u044b\u0440\u043e\u0441 \u043d\u0430 4,5% \u043a \u0442\u043e\u043c\u0443 \u0436\u0435 \u043f\u0435\u0440\u0438\u043e\u0434\u0443 2025 \u0433\u043e\u0434\u0430, \u0434\u0430\u043d\u043d\u044b\u0435 \u043e\u043f\u0443\u0431\u043b\u0438\u043a\u043e\u0432\u0430\u043b\u0438 19 \u043e\u043a\u0442\u044f\u0431\u0440\u044f. \u0410\u043d\u0430\u043b\u0438\u0442\u0438\u043a\u0438 \u0436\u0434\u0430\u043b\u0438 4,4%. \u0412\u043e II \u043a\u0432\u0430\u0440\u0442\u0430\u043b\u0435 \u0440\u043e\u0441\u0442 \u0431\u044b\u043b 4,3%, \u043c\u0438\u043d\u0438\u043c\u0430\u043b\u044c\u043d\u044b\u0439 \u0441 2022 \u0433\u043e\u0434\u0430. \u041a \u043f\u0440\u0435\u0434\u044b\u0434\u0443\u0449\u0435\u043c\u0443 \u043a\u0432\u0430\u0440\u0442\u0430\u043b\u0443 \u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0430 \u043f\u0440\u0438\u0431\u0430\u0432\u0438\u043b\u0430 1,2%. \u0417\u0430 9 \u043c\u0435\u0441\u044f\u0446\u0435\u0432 \u0440\u043e\u0441\u0442 \u0441\u043e\u0441\u0442\u0430\u0432\u0438\u043b 4,6%, \u0430 \u0412\u0412\u041f \u0437\u0430 \u044d\u0442\u043e \u0432\u0440\u0435\u043c\u044f — 107,1 \u0442\u0440\u043b\u043d \u044e\u0430\u043d\u0435\u0439. \u0426\u0435\u043b\u044c \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0430 \u043d\u0430 \u0433\u043e\u0434 4,5–5%, \u0438 \u043f\u043e\u0441\u043b\u0435 \u044d\u0442\u0438\u0445 \u0434\u0430\u043d\u043d\u044b\u0445 \u043e\u043d\u0430 \u0432\u044b\u0433\u043b\u044f\u0434\u0438\u0442 \u0434\u043e\u0441\u0442\u0438\u0436\u0438\u043c\u043e\u0439."},{"id":"b002","kind":"paragraph","text":"\u0413\u043b\u0430\u0432\u043d\u044b\u0439 \u0432\u043a\u043b\u0430\u0434 \u0434\u0430\u043b \u044d\u043a\u0441\u043f\u043e\u0440\u0442. \u0412 \u0441\u0435\u043d\u0442\u044f\u0431\u0440\u0435 \u043e\u043d \u0432\u044b\u0440\u043e\u0441 \u043d\u0430 36,3% \u043a \u043f\u0440\u043e\u0448\u043b\u043e\u043c\u0443 \u0433\u043e\u0434\u0443, \u0438\u043c\u043f\u043e\u0440\u0442 \u043d\u0430 31%. \u0417\u0430 \u043c\u0435\u0441\u044f\u0446 \u041a\u0438\u0442\u0430\u0439 \u043f\u0440\u043e\u0434\u0430\u043b \u0437\u0430 \u0440\u0443\u0431\u0435\u0436 \u0442\u043e\u0432\u0430\u0440\u043e\u0432 \u043d\u0430 $133,5 \u043c\u043b\u0440\u0434 \u0431\u043e\u043b\u044c\u0448\u0435, \u0447\u0435\u043c \u043a\u0443\u043f\u0438\u043b, \u044d\u0442\u043e \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0439 \u0440\u0430\u0437\u0440\u044b\u0432 \u0437\u0430 20 \u043c\u0435\u0441\u044f\u0446\u0435\u0432. \u042d\u043a\u0441\u043f\u043e\u0440\u0442 \u043c\u0438\u043a\u0440\u043e\u0441\u0445\u0435\u043c \u0437\u0430 9 \u043c\u0435\u0441\u044f\u0446\u0435\u0432 \u0432\u044b\u0440\u043e\u0441 \u0432 \u0434\u0435\u043d\u044c\u0433\u0430\u0445 \u0432\u0434\u0432\u043e\u0435, \u043a\u043e\u043c\u043f\u044c\u044e\u0442\u0435\u0440\u043e\u0432 \u0438 \u0430\u0432\u0442\u043e\u043c\u043e\u0431\u0438\u043b\u0435\u0439 \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u043d\u0430 54%. \u041f\u0440\u043e\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u043e\u0435 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u0432 \u0441\u0435\u043d\u0442\u044f\u0431\u0440\u0435 \u0432\u044b\u0440\u043e\u0441\u043b\u043e \u043d\u0430 5,5%."},{"id":"b003","kind":"paragraph","text":"\u0412\u043d\u0443\u0442\u0440\u0438 \u0441\u0442\u0440\u0430\u043d\u044b \u043a\u0430\u0440\u0442\u0438\u043d\u0430 \u0434\u0440\u0443\u0433\u0430\u044f. \u0420\u043e\u0437\u043d\u0438\u0447\u043d\u044b\u0435 \u043f\u0440\u043e\u0434\u0430\u0436\u0438 \u0432 \u0441\u0435\u043d\u0442\u044f\u0431\u0440\u0435 \u0432\u044b\u0440\u043e\u0441\u043b\u0438 \u043d\u0430 1,1%, \u044d\u0442\u043e \u043b\u0443\u0447\u0448\u0435 \u043e\u0436\u0438\u0434\u0430\u043d\u0438\u0439 0,5%, \u043d\u043e \u0432\u0441\u0451 \u0440\u0430\u0432\u043d\u043e \u043c\u0430\u043b\u043e. \u0418\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0438 \u0432 \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u0439 \u043a\u0430\u043f\u0438\u0442\u0430\u043b \u0437\u0430 9 \u043c\u0435\u0441\u044f\u0446\u0435\u0432 \u0441\u043d\u0438\u0437\u0438\u043b\u0438\u0441\u044c \u043d\u0430 7,2%, \u0447\u0430\u0441\u0442\u043d\u044b\u0435 \u043d\u0430 10,4%, \u0432\u043b\u043e\u0436\u0435\u043d\u0438\u044f \u0432 \u0441\u0442\u0440\u043e\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u0436\u0438\u043b\u044c\u044f \u043d\u0430 20,6%. \u041f\u0440\u043e\u0434\u0430\u0436\u0438 \u043d\u043e\u0432\u044b\u0445 \u043a\u0432\u0430\u0440\u0442\u0438\u0440 \u043f\u043e \u043f\u043b\u043e\u0449\u0430\u0434\u0438 \u0443\u043f\u0430\u043b\u0438 \u043d\u0430 13,2%. \u0411\u043e\u043b\u044c\u0448\u0430\u044f \u0447\u0430\u0441\u0442\u044c \u0441\u0431\u0435\u0440\u0435\u0436\u0435\u043d\u0438\u0439 \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u0445 \u0441\u0435\u043c\u0435\u0439 \u0432\u043b\u043e\u0436\u0435\u043d\u0430 \u0432 \u043a\u0432\u0430\u0440\u0442\u0438\u0440\u044b, \u0438 \u043a\u043e\u0433\u0434\u0430 \u0436\u0438\u043b\u044c\u0451 \u0434\u0435\u0448\u0435\u0432\u0435\u0435\u0442, \u043b\u044e\u0434\u0438 \u0447\u0443\u0432\u0441\u0442\u0432\u0443\u044e\u0442 \u0441\u0435\u0431\u044f \u0431\u0435\u0434\u043d\u0435\u0435 \u0438 \u0442\u0440\u0430\u0442\u044f\u0442 \u043e\u0441\u0442\u043e\u0440\u043e\u0436\u043d\u0435\u0435."},{"id":"b004","kind":"paragraph","text":"\u041f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u043c \u0441\u0435\u043c\u0435\u0439\u043d\u043e\u0435 \u043a\u0430\u0444\u0435, \u043a\u043e\u0442\u043e\u0440\u043e\u0435 \u043d\u0430\u0447\u0430\u043b\u043e \u0432\u043e\u0437\u0438\u0442\u044c \u043f\u0438\u0440\u043e\u0433\u0438 \u0432 \u0441\u043e\u0441\u0435\u0434\u043d\u0438\u0439 \u0433\u043e\u0440\u043e\u0434. \u0412\u044b\u0440\u0443\u0447\u043a\u0430 \u0440\u0430\u0441\u0442\u0451\u0442, \u043f\u043e\u0432\u0430\u0440\u0430 \u0437\u0430\u043d\u044f\u0442\u044b, \u043d\u043e \u0436\u0438\u0442\u0435\u043b\u0438 \u0441\u0432\u043e\u0435\u0433\u043e \u0440\u0430\u0439\u043e\u043d\u0430 \u0437\u0430\u0445\u043e\u0434\u044f\u0442 \u0432\u0441\u0451 \u0440\u0435\u0436\u0435. \u041f\u043e\u043a\u0430 \u0441\u043e\u0441\u0435\u0434\u0438 \u043f\u043e\u043a\u0443\u043f\u0430\u044e\u0442, \u043a\u0430\u0444\u0435 \u0436\u0438\u0432\u0451\u0442 \u0445\u043e\u0440\u043e\u0448\u043e. \u0421\u0442\u043e\u0438\u0442 \u0438\u043c \u043d\u0430\u0439\u0442\u0438 \u0434\u0440\u0443\u0433\u0443\u044e \u043f\u0435\u043a\u0430\u0440\u043d\u044e, \u0438 \u0440\u043e\u0441\u0442 \u0437\u0430\u043a\u043e\u043d\u0447\u0438\u0442\u0441\u044f, \u043f\u043e\u0442\u043e\u043c\u0443 \u0447\u0442\u043e \u0441\u0432\u043e\u0438\u0445 \u043a\u043b\u0438\u0435\u043d\u0442\u043e\u0432 \u043a\u0430\u0444\u0435 \u043d\u0435 \u043d\u0430\u0440\u0430\u0441\u0442\u0438\u043b\u043e. \u042d\u043a\u043e\u043d\u043e\u043c\u0438\u0441\u0442\u044b \u043d\u0430\u0437\u044b\u0432\u0430\u044e\u0442 \u044d\u0442\u043e \u0440\u043e\u0441\u0442\u043e\u043c \u0437\u0430 \u0441\u0447\u0451\u0442 \u0432\u043d\u0435\u0448\u043d\u0435\u0433\u043e \u0441\u043f\u0440\u043e\u0441\u0430. \u041e\u043d \u0431\u044b\u0441\u0442\u0440\u044b\u0439, \u043d\u043e \u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u043e\u0442 \u0447\u0443\u0436\u0438\u0445 \u0440\u0435\u0448\u0435\u043d\u0438\u0439: \u0415\u0432\u0440\u043e\u0441\u043e\u044e\u0437 \u0443\u0436\u0435 \u0434\u043e\u0431\u0438\u0432\u0430\u0435\u0442\u0441\u044f, \u0447\u0442\u043e\u0431\u044b \u041a\u0438\u0442\u0430\u0439 \u043c\u0435\u043d\u044c\u0448\u0435 \u043f\u0440\u043e\u0434\u0430\u0432\u0430\u043b \u0435\u043c\u0443 \u0434\u043e\u0440\u043e\u0433\u0438\u0445 \u0442\u043e\u0432\u0430\u0440\u043e\u0432."},{"id":"b005","kind":"paragraph","text":"\u0414\u043b\u044f \u0420\u043e\u0441\u0441\u0438\u0438 \u044d\u0442\u043e \u0432\u043e\u043f\u0440\u043e\u0441 \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u043d\u043e\u0439 \u0432\u044b\u0440\u0443\u0447\u043a\u0438. \u041a\u0438\u0442\u0430\u0439 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0439 \u043f\u043e\u043a\u0443\u043f\u0430\u0442\u0435\u043b\u044c \u0440\u043e\u0441\u0441\u0438\u0439\u0441\u043a\u043e\u0433\u043e \u0442\u043e\u043f\u043b\u0438\u0432\u0430: \u0432 \u0441\u0435\u043d\u0442\u044f\u0431\u0440\u0435 \u043e\u043d \u043a\u0443\u043f\u0438\u043b \u043d\u0435\u0444\u0442\u0438, \u0433\u0430\u0437\u0430 \u0438 \u0443\u0433\u043b\u044f \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u043d\u0430 9,1 \u043c\u043b\u0440\u0434 \u0435\u0432\u0440\u043e. \u0417\u0430\u0433\u0440\u0443\u0436\u0435\u043d\u043d\u044b\u0435 \u0437\u0430\u0432\u043e\u0434\u044b \u043f\u043e\u0442\u0440\u0435\u0431\u043b\u044f\u044e\u0442 \u0431\u043e\u043b\u044c\u0448\u0435 \u044d\u043d\u0435\u0440\u0433\u0438\u0438, \u0438 \u043f\u043e\u043a\u0430 \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u043d\u044b\u0435 \u0437\u0430\u043a\u0430\u0437\u044b \u0438\u0434\u0443\u0442, \u0441\u043f\u0440\u043e\u0441 \u043d\u0430 \u0441\u044b\u0440\u044c\u0451 \u0434\u0435\u0440\u0436\u0438\u0442\u0441\u044f. \u0421\u0438\u043b\u044c\u043d\u044b\u0435 \u0434\u0430\u043d\u043d\u044b\u0435 \u0443\u043c\u0435\u043d\u044c\u0448\u0430\u044e\u0442 \u0448\u0430\u043d\u0441\u044b \u043d\u0430 \u043d\u043e\u0432\u044b\u0435 \u043c\u0435\u0440\u044b \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0438 \u0432\u043d\u0443\u0442\u0440\u0435\u043d\u043d\u0435\u0433\u043e \u0441\u043f\u0440\u043e\u0441\u0430: \u043a\u043e\u0433\u0434\u0430 \u043f\u043b\u0430\u043d \u0432\u044b\u043f\u043e\u043b\u043d\u044f\u0435\u0442\u0441\u044f, \u0443 \u041f\u0435\u043a\u0438\u043d\u0430 \u043c\u0435\u043d\u044c\u0448\u0435 \u043f\u0440\u0438\u0447\u0438\u043d \u0442\u0440\u0430\u0442\u0438\u0442\u044c \u0434\u0435\u043d\u044c\u0433\u0438 \u043d\u0430 \u0441\u0442\u0438\u043c\u0443\u043b\u044b."},{"id":"b006","kind":"paragraph","text":"\u0421\u0442\u0430\u0440\u0448\u0438\u0439 \u044d\u043a\u043e\u043d\u043e\u043c\u0438\u0441\u0442 Economist Intelligence Unit \u0422\u044f\u043d\u044c\u0447\u044d\u043d\u044c \u0421\u044e\u0439 \u0436\u0434\u0451\u0442, \u0447\u0442\u043e \u044d\u043a\u0441\u043f\u043e\u0440\u0442 \u0438 \u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0435 \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0438 \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u0430\u0442 \u0440\u043e\u0441\u0442 \u0438 \u0432 IV \u043a\u0432\u0430\u0440\u0442\u0430\u043b\u0435. \u0420\u0438\u0441\u043a \u0432 \u0442\u043e\u043c, \u0447\u0442\u043e \u043e\u043f\u043e\u0440\u0430 \u043e\u0434\u043d\u0430. \u0417\u0430\u043c\u0435\u0434\u043b\u0435\u043d\u0438\u0435 \u043c\u0438\u0440\u043e\u0432\u044b\u0445 \u0432\u043b\u043e\u0436\u0435\u043d\u0438\u0439 \u0432 \u0438\u0441\u043a\u0443\u0441\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u0438\u043d\u0442\u0435\u043b\u043b\u0435\u043a\u0442 \u0438\u043b\u0438 \u0431\u0430\u0440\u044c\u0435\u0440\u044b \u0415\u0432\u0440\u043e\u0441\u043e\u044e\u0437\u0430 \u0443\u0434\u0430\u0440\u044f\u0442 \u043f\u043e \u043f\u0440\u043e\u0434\u0430\u0436\u0430\u043c \u043c\u0438\u043a\u0440\u043e\u0441\u0445\u0435\u043c \u0438 \u043c\u0430\u0448\u0438\u043d, \u0430 \u0441\u0432\u043e\u0438 \u043f\u043e\u043a\u0443\u043f\u0430\u0442\u0435\u043b\u0438 \u043f\u043e\u043a\u0430 \u043d\u0435 \u0433\u043e\u0442\u043e\u0432\u044b \u0437\u0430\u043c\u0435\u043d\u0438\u0442\u044c \u0447\u0443\u0436\u0438\u0445. \u0421\u043e\u0445\u0440\u0430\u043d\u0435\u043d\u0438\u0435 \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u043d\u043e\u0433\u043e \u0441\u043f\u0440\u043e\u0441\u0430 \u0434\u0435\u0440\u0436\u0438\u0442 \u0437\u0430\u0432\u043e\u0434\u044b \u041a\u0438\u0442\u0430\u044f \u0437\u0430\u0433\u0440\u0443\u0436\u0435\u043d\u043d\u044b\u043c\u0438, \u0430 \u0432\u043c\u0435\u0441\u0442\u0435 \u0441 \u043d\u0438\u043c\u0438 \u0438 \u0437\u0430\u043a\u0443\u043f\u043a\u0438 \u0440\u043e\u0441\u0441\u0438\u0439\u0441\u043a\u043e\u0439 \u043d\u0435\u0444\u0442\u0438. \u0415\u0433\u043e \u043e\u0441\u043b\u0430\u0431\u043b\u0435\u043d\u0438\u0435 \u043f\u0440\u043e\u0432\u0435\u0440\u0438\u0442, \u043d\u0430\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0431\u044b\u0441\u0442\u0440\u043e \u041f\u0435\u043a\u0438\u043d \u0441\u043c\u043e\u0436\u0435\u0442 \u0440\u0430\u0437\u043e\u0433\u043d\u0430\u0442\u044c \u043f\u043e\u0442\u0440\u0435\u0431\u043b\u0435\u043d\u0438\u0435 \u0432\u043d\u0443\u0442\u0440\u0438 \u0441\u0442\u0440\u0430\u043d\u044b."},{"id":"b007","kind":"heading","text":"\u041d\u0430\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0432\u044b\u0440\u043e\u0441 \u0412\u0412\u041f \u041a\u0438\u0442\u0430\u044f \u0432 III \u043a\u0432\u0430\u0440\u0442\u0430\u043b\u0435 2026 \u0433\u043e\u0434\u0430?"},{"id":"b008","kind":"paragraph","text":"\u041d\u0430 4,5% \u043a \u0438\u044e\u043b\u044e–\u0441\u0435\u043d\u0442\u044f\u0431\u0440\u044e 2025 \u0433\u043e\u0434\u0430. \u0410\u043d\u0430\u043b\u0438\u0442\u0438\u043a\u0438 \u0436\u0434\u0430\u043b\u0438 4,4%, \u0432\u043e II \u043a\u0432\u0430\u0440\u0442\u0430\u043b\u0435 \u0440\u043e\u0441\u0442 \u0431\u044b\u043b 4,3%, \u043c\u0438\u043d\u0438\u043c\u0430\u043b\u044c\u043d\u044b\u0439 \u0441 2022 \u0433\u043e\u0434\u0430. \u0417\u0430 9 \u043c\u0435\u0441\u044f\u0446\u0435\u0432 \u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0430 \u0432\u044b\u0440\u043e\u0441\u043b\u0430 \u043d\u0430 4,6% \u043f\u0440\u0438 \u0446\u0435\u043b\u0438 \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0430 4,5–5%."},{"id":"b009","kind":"heading","text":"\u041f\u043e\u0447\u0435\u043c\u0443 \u0440\u043e\u0441\u0442 \u041a\u0438\u0442\u0430\u044f \u043d\u0430\u0437\u044b\u0432\u0430\u044e\u0442 \u043d\u0435\u0441\u0431\u0430\u043b\u0430\u043d\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u043c?"},{"id":"b010","kind":"paragraph","text":"\u042d\u043a\u0441\u043f\u043e\u0440\u0442 \u0432 \u0441\u0435\u043d\u0442\u044f\u0431\u0440\u0435 \u0432\u044b\u0440\u043e\u0441 \u043d\u0430 36,3%, \u0430 \u0440\u043e\u0437\u043d\u0438\u0447\u043d\u044b\u0435 \u043f\u0440\u043e\u0434\u0430\u0436\u0438 \u043d\u0430 1,1%. \u0418\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0438 \u0432 \u043d\u0435\u0434\u0432\u0438\u0436\u0438\u043c\u043e\u0441\u0442\u044c \u0437\u0430 9 \u043c\u0435\u0441\u044f\u0446\u0435\u0432 \u0443\u043f\u0430\u043b\u0438 \u043d\u0430 20,6%. \u042d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0430 \u0440\u0430\u0441\u0442\u0451\u0442 \u0437\u0430 \u0441\u0447\u0451\u0442 \u043f\u043e\u043a\u0443\u043f\u0430\u0442\u0435\u043b\u0435\u0439 \u0437\u0430 \u0440\u0443\u0431\u0435\u0436\u043e\u043c, \u0430 \u043d\u0435 \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0445 \u0436\u0438\u0442\u0435\u043b\u0435\u0439."},{"id":"b011","kind":"heading","text":"\u0427\u0442\u043e \u0443\u0441\u043a\u043e\u0440\u0435\u043d\u0438\u0435 \u041a\u0438\u0442\u0430\u044f \u0437\u043d\u0430\u0447\u0438\u0442 \u0434\u043b\u044f \u0420\u043e\u0441\u0441\u0438\u0438?"},{"id":"b012","kind":"paragraph","text":"\u041a\u0438\u0442\u0430\u0439 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0439 \u043f\u043e\u043a\u0443\u043f\u0430\u0442\u0435\u043b\u044c \u0440\u043e\u0441\u0441\u0438\u0439\u0441\u043a\u043e\u0439 \u043d\u0435\u0444\u0442\u0438, \u0433\u0430\u0437\u0430 \u0438 \u0443\u0433\u043b\u044f. \u041f\u043e\u043a\u0430 \u0435\u0433\u043e \u0437\u0430\u0432\u043e\u0434\u044b \u0437\u0430\u0433\u0440\u0443\u0436\u0435\u043d\u044b \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u043d\u044b\u043c\u0438 \u0437\u0430\u043a\u0430\u0437\u0430\u043c\u0438, \u0441\u043f\u0440\u043e\u0441 \u043d\u0430 \u0442\u043e\u043f\u043b\u0438\u0432\u043e \u0434\u0435\u0440\u0436\u0438\u0442\u0441\u044f. \u0415\u0441\u043b\u0438 \u0432\u043d\u0435\u0448\u043d\u0438\u0439 \u0441\u043f\u0440\u043e\u0441 \u043e\u0441\u043b\u0430\u0431\u043d\u0435\u0442, \u0432\u043d\u0443\u0442\u0440\u0435\u043d\u043d\u0438\u0439 \u0440\u044b\u043d\u043e\u043a \u041a\u0438\u0442\u0430\u044f \u043f\u043e\u043a\u0430 \u043d\u0435 \u0433\u043e\u0442\u043e\u0432 \u0435\u0433\u043e \u0437\u0430\u043c\u0435\u043d\u0438\u0442\u044c."}],"sources":[{"label":"\u0412\u0412\u041f \u041a\u0438\u0442\u0430\u044f \u0432 III \u043a\u0432\u0430\u0440\u0442\u0430\u043b\u0435 \u0432\u044b\u0440\u043e\u0441 \u043d\u0430 4,5%","url":"https://www.interfax.ru/business/1123374"},{"label":"China\'s economic growth quickens as exports surge","url":"https://www.cnbc.com/2026/10/19/chinas-economic-growth-quickens-to-4point6percent-as-exports-surge-stimulus-rolls-out.html"},{"label":"China\'s Growth Rebounds to 4.5%, Puts Annual Target Within Reach","url":"https://www.bloomberg.com/news/articles/2026-10-19/china-s-growth-rebounds-to-4-5-puts-annual-target-within-reach"},{"label":"China Q3 GDP beats forecasts at 4.5%, retail sales grow at fastest pace since March","url":"https://investinglive.com/news/china-q3-gdp-beats-forecasts-at-4-5-retail-sales-grow-at-fastest-pace-since-march/"},{"label":"China\'s economy holds steady in first three quarters of 2026","url":"https://www.indexbox.io/blog/chinas-economy-holds-steady-in-first-three-quarters-of-2026-as-trade-and-industry-outpace-broader-growth/"},{"label":"China\'s exports surge 36.3% in September as pressure ramps up to rebalance trade","url":"https://clickondetroit.com/business/2026/10/14/chinas-exports-surge-363-in-september-as-pressure-ramps-up-to-rebalance-trade"},{"label":"China Posts Biggest Trade Surplus in 20 Months","url":"https://tradingeconomics.com/china/balance-of-trade/news/591695"},{"label":"September 2026 — Monthly analysis of Russian fossil fuel exports and sanctions","url":"https://energyandcleanair.org/september-2026-monthly-analysis-of-russian-fossil-fuel-exports-and-sanctions/"}],"sourceBodySha256":"a43116f5bc45095d81495bfb1beae8eb81d22f98eafffb5342e2297d883572c6"}')}}]);